package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.client.particle.*;import net.minecraft.world.phys.Vec3;
/** Client cosmetics sampled along the exhaust path, admitted by the shared particle cap. */
public final class Pm01Effects {
 public static void step(Pm01Entity e){var m=net.minecraft.client.Minecraft.getInstance();if(e.tickCount==1)m.getSoundManager().play(new Flight(e));int q=Mpl01Config.QUALITY.get();if(q==0||m.level==null||e.getDeltaMovement().lengthSqr()<.01||e.position().distanceToSqr(m.gameRenderer.getMainCamera().getPosition())>128*128)return;if(m.options.particles().get()==net.minecraft.client.ParticleStatus.MINIMAL){if(e.tickCount%3!=0)return;q=1;}var sprites=ExplosionVfxClient.hgSprite(2);if(sprites==null)return;var forward=e.getDeltaMovement().normalize();var at=e.position().subtract(forward.scale(2.825));for(int i=0;i<q;i++){var p=new Trail(m.level,at.subtract(e.getDeltaMovement().scale((i+.5)/q)),sprites,false);if(RubbleVisualBudget.claim(p))m.particleEngine.add(p);}var fire=new Trail(m.level,at,sprites,true);if(RubbleVisualBudget.claim(fire))m.particleEngine.add(fire);}
 private static final class Trail extends TextureSheetParticle{private final boolean fire;Trail(net.minecraft.client.multiplayer.ClientLevel l,Vec3 at,SpriteSet sprites,boolean fire){super(l,at.x,at.y,at.z);this.fire=fire;setSprite(sprites.get(8+l.random.nextInt(6),15));lifetime=fire?6:28+l.random.nextInt(15);quadSize=fire?.23f:.14f;rCol=fire?1:.78f;gCol=fire?.5f:.79f;bCol=fire?.08f:.77f;alpha=fire?.85f:.38f;roll=oRoll=l.random.nextFloat()*6.283f;xd=(l.random.nextFloat()-.5)*.01;yd=.006;zd=(l.random.nextFloat()-.5)*.01;hasPhysics=false;}@Override public void tick(){xo=x;yo=y;zo=z;if(++age>=lifetime){remove();return;}x+=xd;y+=yd;z+=zd;quadSize*=fire?1:1.035f;alpha=(fire?.85f:.38f)*Math.min(1,(lifetime-age)/(fire?3f:12f));}@Override public ParticleRenderType getRenderType(){return fire?ParticleRenderType.PARTICLE_SHEET_LIT:ParticleRenderType.PARTICLE_SHEET_TRANSLUCENT;}@Override public int getLightColor(float p){return fire?0xf000f0:super.getLightColor(p);}}
 private static final class Flight extends net.minecraft.client.resources.sounds.AbstractTickableSoundInstance{
  private final Pm01Entity missile;Flight(Pm01Entity e){super(com.atsuishio.superbwarfare.init.ModSounds.ROCKET_ENGINE.get(),net.minecraft.sounds.SoundSource.HOSTILE,net.minecraft.util.RandomSource.create());missile=e;looping=true;delay=0;volume=.28f;pitch=1;relative=false;attenuation=net.minecraft.client.resources.sounds.SoundInstance.Attenuation.LINEAR;x=e.getX();y=e.getY();z=e.getZ();}
  @Override public void tick(){if(missile.isRemoved()||net.minecraft.client.Minecraft.getInstance().level!=missile.level()){stop();return;}x=missile.getX();y=missile.getY();z=missile.getZ();}
 }
 private Pm01Effects(){}
}
